import {
  debounce,
  validatePassword,
} from '/static/js/common/functions.prod.js';
import {
  showOutput,
  clearOutput,
} from '/static/js/common/notification.prod.js';
document.addEventListener('DOMContentLoaded', function () {
  ($('main').on(
    'input',
    '#username',
    debounce(function (t) {
      const e = t.target.value
        .toLowerCase()
        .trim()
        .replace(/[^a-zA-Z0-9_]/g, '');
      ((t.target.value = e),
        e.length <= 4
          ? showOutput('Username too short.')
          : e.length > 12
            ? showOutput('Username too long.')
            : $.ajax({
                type: 'GET',
                url: `/?action=check_username&username=${e}`,
                success: function (t) {
                  'valid' == t.status
                    ? showOutput('Username is unique.', !0)
                    : showOutput('Username already taken.');
                },
              }));
    })
  ),
    $('main').on(
      'input',
      '#password1, #reppassword1',
      debounce(function (t) {
        let e = t.target.value.trim();
        $(this).val(e);
        const o = validatePassword(e);
        o ? showOutput(o) : clearOutput();
      })
    ),
    $('main').on(
      'input',
      '#password2, #reppassword2',
      debounce(function (t) {
        let e = t.target.value.trim(),
          o = 'password2' === t.target.id ? '#password1' : '#reppassword1';
        e === $(o).val()
          ? clearOutput()
          : showOutput('Passwords do not match.');
      })
    ),
    window.visualViewport?.addEventListener('resize', () => {
      document.documentElement.style.setProperty(
        '--vh',
        `${window.visualViewport.height}px`
      );
    }));
});
